const a=new IntersectionObserver(t=>{t.forEach(e=>{e.isIntersecting&&(e.target.classList.add("on"),a.unobserve(e.target))})},{threshold:.12});document.querySelectorAll(".reveal").forEach(t=>a.observe(t));const r=1;document.addEventListener("pointermove",t=>{document.querySelectorAll("[data-magnet]").forEach(e=>{const n=e.getBoundingClientRect(),l=n.left+n.width/2,i=n.top+n.height/2,o=t.clientX-l,s=t.clientY-i,m=Math.hypot(o,s),h=Math.max(n.width,n.height)*1.25,c=Math.max(0,1-m/h),u=o/n.width*r*c,g=s/n.height*r*c;e.style.transform=`translate(${u.toFixed(2)}px, ${g.toFixed(2)}px)`})},{passive:!0});document.addEventListener("pointerleave",()=>{document.querySelectorAll("[data-magnet]").forEach(t=>{t.style.transform="translate(0,0)"})},!0);(function(){try{const t=localStorage.getItem("theme");t==="dark"?document.documentElement.classList.add("dark"):t==="light"?document.documentElement.classList.remove("dark"):window.matchMedia("(prefers-color-scheme: dark)").matches&&document.documentElement.classList.add("dark")}catch{}})();document.getElementById("y").textContent=new Date().getFullYear();const y=document.getElementById("scroll-progress-bar"),d=()=>{const t=window.scrollY,e=document.documentElement.scrollHeight-window.innerHeight;y.style.width=(e?t/e*100:0)+"%"};d();addEventListener("scroll",d,{passive:!0});
